+import { describe, expect, test } from 'bun:test';
+import { resolve } from 'node:path';
+import { OperatorRuntime } from '@agentic-ddd/runtime';
+import { covers, FakeLlm } from '@agentic-ddd/testing';
+import { TaskCompleted, TaskCreated } from '../domain/task.events';
+import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';
+import { CreateTask } from '../application/create-task';
+import { CompleteTask } from '../application/complete-task';
+import { TaskOperator } from '../operators/task.operator';
+
+describe('task-operator', () => {
+  test(covers(['operator:task-operator', 'criterion:0001/tools'], 'cria e conclui a tarefa usando somente create_task e complete_task e publica os dois eventos'), async () => {
+    const repo = new InMemoryTaskRepository();
+    const llm = new FakeLlm([
+      { stopReason: 'tool_calls', content: [{ type: 'tool_call', id: 'c1', name: 'create_task', input: { task_id: 't1', title: 'Comprar pão' } }] },
+      { stopReason: 'tool_calls', content: [{ type: 'tool_call', id: 'c2', name: 'complete_task', input: { task_id: 't1' } }] },
+      { stopReason: 'end', content: [{ type: 'text', text: 'Pronto.' }] },
+    ]);
+    const runtime = new OperatorRuntime({
+      llm,
+      root: resolve(import.meta.dir, '../..'),
+      modules: [{ name: 'tasks', path: 'app' }],
+    });
+    await runtime.register(TaskOperator, new Map<any, any>([
+      [CreateTask, new CreateTask(repo)],
+      [CompleteTask, new CompleteTask(repo)],
+    ]));
+
+    const result = await runtime.run('task-operator', { message: 'Crie a tarefa t1 e conclua-a.' });
+
+    expect(result.status).toBe('completed');
+    expect(result.output).toBe('Pronto.');
+    expect(llm.requests[0]!.tools.map((t) => t.name)).toEqual(['complete_task', 'create_task']);
+    expect(result.steps.flatMap((s) => s.tools.map((t) => t.result!.isError))).toEqual([false, false]);
+    expect((await repo.findById('t1'))!.status).toBe('completed');
+    expect(result.events).toHaveLength(2);
+    expect(result.events[0]).toBeInstanceOf(TaskCreated);
+    expect(result.events[1]).toBeInstanceOf(TaskCompleted);
+  });
+});

